import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";


const AllListings = () => {
  const userId = sessionStorage.getItem("userId");
  const [listings, setListings] = useState([]);
  const [favorites, setFavorites] = useState([]);

  useEffect(() => {
    fetch(`${API_BASE_URL}/api/listings`)
      .then((res) => res.json())
      .then((data) => {
        const filtered = data.filter(
          (item) => String(item.user_id) !== String(userId) && !item.sold
        );
        setListings(filtered);
      })
      .catch((err) => console.error("Error fetching listings:", err));

    if (userId) {
      fetch(`${API_BASE_URL}/api/favorites/user/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          setFavorites(data.map((fav) => fav.id)); // Only keep listing IDs
        })
        .catch((err) => console.error("Failed to load favorites:", err));
    }
  }, [userId]);

  const handleBuy = async (item) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/cart`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: userId,
          listing_id: item.id,
          title: item.title,
          price: item.price,
          condition: item.condition,
          description: item.description,
          image: item.image,
        }),
      });

      if (response.ok) {
        alert("Item added to cart!");
      } else {
        alert("Failed to add to cart.");
      }
    } catch (err) {
      console.error("Buy error:", err);
      alert("Something went wrong.");
    }
  };

  const handleAddFavorite = async (itemId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/favorites`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: userId, listing_id: itemId }),
      });

      if (response.ok) {
        setFavorites((prev) => [...prev, itemId]);
        alert("Added to favorites!");
      } else {
        alert("Failed to favorite.");
      }
    } catch (err) {
      console.error("Favorite error:", err);
      alert("Something went wrong.");
    }
  };
  const handleFlag = async (listingId) => {
    const userId = sessionStorage.getItem("userId");
    if (!userId) return alert("You must be logged in to flag listings.");
  
    const reason = prompt("Why are you flagging this listing? (optional)");
  
    const res = await fetch(`${API_BASE_URL}/api/listings/flag`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: userId,
        listing_id: listingId,
        reason: reason || "No reason provided"
      }),
    });
  
    const data = await res.json();
    if (res.ok) {
      alert("Listing flagged.");
    } else {
      alert(data.message || "Failed to flag listing.");
    }
  };
  
  return (
    <div className="dashboard-wrapper" style={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <Navbar />
      <main className="dashboard-main" style={{ flex: 1, padding: "32px 48px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>Explore All Listings</h2>

        <div className="item-grid">
          {listings.length > 0 ? (
            listings.map((item) => (
              <div className="item-card" key={item.id}>
                <div className="image-placeholder">
                  {item.image ? <img src={item.image} alt={item.title} /> : <span>No Image</span>}
                </div>
                <h4>{item.title}</h4>
                <p>{item.description}</p>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                <div className="item-actions" style={{ display: "flex", justifyContent: "space-between" }}>
                  <button className="buy-btn" onClick={() => handleBuy(item)}>Buy</button>
                  <button
                    className="favorite-btn"
                    onClick={() => handleAddFavorite(item.id)}
                    disabled={favorites.includes(item.id)}
                  >
                    {favorites.includes(item.id) ? "❤️ Favorited" : "🤍 Favorite"}
                  </button>
                </div>
              </div>
            ))
          ) : (
            <p style={{ textAlign: "center" }}>No listings available from other users.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default AllListings;
